#include <vector>
using namespace std;

class Solution {
    bool backtrack(int idx, int n, int size, vector<int>& res, vector<bool>& used) {
        while (idx < size && res[idx] != 0) idx++;
        if (idx == size) return true;
        for (int num = n; num >= 1; --num) {
            if (used[num]) continue;
            if (num == 1) {
                res[idx] = 1;
                used[1] = true;
                if (backtrack(idx + 1, n, size, res, used)) return true;
                res[idx] = 0;
                used[1] = false;
            } else {
                if (idx + num < size && res[idx + num] == 0) {
                    res[idx] = num;
                    res[idx + num] = num;
                    used[num] = true;
                    if (backtrack(idx + 1, n, size, res, used)) return true;
                    res[idx] = 0;
                    res[idx + num] = 0;
                    used[num] = false;
                }
            }
        }
        return false;
    }

public:
