var constructDistancedSequence = function(n) {
    const size = 2 * n - 1;
    const res = Array(size).fill(0);
    const used = Array(n + 1).fill(false);

    function backtrack(idx) {
        while (idx < size && res[idx] !== 0) idx++;
        if (idx === size) return true;
        for (let num = n; num >= 1; --num) {
            if (used[num]) continue;
            if (num === 1) {
                res[idx] = 1;
                used[1] = true;
                if (backtrack(idx + 1)) return true;
                res[idx] = 0;
                used[1] = false;
            } else {
                if (idx + num < size && res[idx + num] === 0) {
                    res[idx] = num;
                    res[idx + num] = num;
                    used[num] = true;
                    if (backtrack(idx + 1)) return true;
                    res[idx] = 0;
                    res[idx + num] = 0;
                    used[num] = false;
                }
            }
        }
        return false;
    }

    backtrack(0);
    return res;
